  // Actions POST through fetch: record them instead (this page only).
  var posted = [];
  window.fetch = function (url, opts) {
    posted.push(JSON.parse(opts.body));
    return Promise.resolve(new Response('data: {"type":"RUN_STARTED"}\n\ndata: {"type":"RUN_FINISHED"}\n\n',
                                        { status: 200 }));
  };
  function linkWait(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }
  // Click a link and report whether its default was prevented; the page
  // never navigates (the fixture prevents what the component left).
  function clickLink(fx, a, init) {
    var prevented = null;
    var spy = function (e) { prevented = e.defaultPrevented; e.preventDefault(); };
    fx.addEventListener("click", spy);
    T.fire(a, "click", Object.assign({ button: 0 }, init || {}));
    fx.removeEventListener("click", spy);
    return prevented;
  }
  function hrefOf(el, sel) { return el.querySelector(sel).getAttribute("href"); }
